open class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)

    val client = OkHttpClient()

    // Ensure we are compiling against the right variant
    println(AndroidPlatform.isSupported)

    val url = "https://github.com/lysine-dev/okhttp".toHttpUrl()
    println(url.topPrivateDomain())

    client.newCall(Request(url)).enqueue(
      object : Callback {
        override fun onFailure(
          call: Call,
          e: IOException,
        ) {
          println("failed: $e")
        }

        override fun onResponse(
          call: Call,
          response: Response,
        ) {
          println("response: ${response.code}")
          response.close()
        }
      },
    )
  }
}

  saveCookieJar(immediate = false) {
    // Debounced write to avoid excessive disk I/O during rapid request bursts
    if (immediate) {
      if (this.#saveTimerId) {
        clearTimeout(this.#saveTimerId);
        this.#saveTimerId = null;
      }
      return this.writeCookieJar();
    }

    if (!this.#debounceStart) {
      this.#debounceStart = Date.now();
    }

    if (this.#saveTimerId) {
      clearTimeout(this.#saveTimerId);
    }
    this.#saveTimerId = setTimeout(() => {
      this.writeCookieJar();
      this.#saveTimerId = null;
    }, DEBOUNCE_MS);
  }
}
